-- Generated by tools/make_wallpapers.py from content/wallpapers/sources.json. Do not edit by hand.
-- Photos from Unsplash (https://unsplash.com), free to use under the Unsplash License; the image
-- files are in supabase/wallpapers/ and go to the Storage bucket `wallpapers` (supabase seed buckets).

on conflict (id) do update set
  url = excluded.url, width = excluded.width, height = excluded.height, color = excluded.color, focus_y = excluded.focus_y,
  author = excluded.author, author_url = excluded.author_url, source_url = excluded.source_url,
  licence = excluded.licence, active = true;
